using Allegiance.Core.Rendering;
using Microsoft.Xna.Framework;
using Microsoft.Xna.Framework.Graphics;

namespace Allegiance.ClientCore.MonoGame.Rendering;

/// <summary>
/// P529 — uploads a rock diffuse as a <b>mipmapped</b> <see cref="Texture2D"/>
/// so minified-at-distance rocks stop aliasing (colour shimmer/jump as the
/// camera or rock moves — one of the three P529 causes). The chain itself is
/// generated by the pure, headlessly-testable <see cref="MipmapChain"/> in
/// <c>Allegiance.Core</c>; this is only the GPU-upload boundary, converting the
/// <c>Color[]</c> base plane the pipeline already produces.
///
/// Used by every rock texture creation path: the shared procedural diffuse in
/// <see cref="AsteroidRenderer"/>'s ctor, the P421 real <c>bgrndNNbmp</c>
/// surfaces in <see cref="RockTextures.Load"/>, and the procedural fallback in
/// <c>Game1.EnsureAsteroidTexture</c>.
/// </summary>
public static class TextureMipmapBuilder
{
    /// <summary>
    /// Create a square/rectangular mipmapped <see cref="Texture2D"/> from a
    /// full-resolution <see cref="Color"/> plane, uploading every level of the
    /// generated chain. Level 0 uses the exact <c>Color[]</c> given (byte-identical
    /// to the pre-P529 path); levels 1..N are the box-filtered chain.
    /// </summary>
    public static Texture2D CreateMipmapped(GraphicsDevice gd, Color[] basePixels, int width, int height)
    {
        var tex = new Texture2D(gd, width, height, mipmap: true, SurfaceFormat.Color);
        tex.SetData(basePixels);                       // level 0, byte-identical as before

        var plane = ToRgba(basePixels);
        int w = width, h = height;
        int levels = MipmapChain.LevelCount(width, height);
        for (int level = 1; level < levels; level++)
        {
            var next = MipmapChain.Downsample(plane, w, h);
            MipmapChain.NextLevelSize(w, h, out w, out h);
            tex.SetData(level, null, ToColor(next), 0, next.Length);
            plane = next;
        }
        return tex;
    }

    private static Rgba32[] ToRgba(Color[] colors)
    {
        var rgba = new Rgba32[colors.Length];
        for (int i = 0; i < colors.Length; i++)
        {
            var c = colors[i];
            rgba[i] = new Rgba32(c.R, c.G, c.B, c.A);
        }
        return rgba;
    }

    private static Color[] ToColor(Rgba32[] rgba)
    {
        var colors = new Color[rgba.Length];
        for (int i = 0; i < rgba.Length; i++)
            colors[i] = new Color(rgba[i].R, rgba[i].G, rgba[i].B, rgba[i].A);
        return colors;
    }
}
